function candy(ratings: number[]): number {
  const n = ratings.length;
  // Каждому минимум по одной конфете
  const candies = new Array<number>(n).fill(1);

  // Проход слева направо: учитываем только левого соседа
  for (let i = 1; i < n; i++) {
    if (ratings[i] > ratings[i - 1]) {
      candies[i] = candies[i - 1] + 1;
    }
  }

  // Проход справа налево: учитываем правого соседа,
  // не ломая уже выполненное условие для левого (берём максимум)
  for (let i = n - 2; i >= 0; i--) {
    if (ratings[i] > ratings[i + 1]) {
      candies[i] = Math.max(candies[i], candies[i + 1] + 1);
    }
  }

  // Суммируем итоговое распределение
  let total = 0;
  for (const c of candies) total += c;
  return total;
}

// Время: O(n) — два прохода
// Память: O(n) — массив конфет
